"""Continue the pinned 0211 installer with a corrected release-version check.
The original payload identity and signed Android cache remain unchanged.
All original preflight, media, session, ledger and rollback guards still run.
"""
ORIGINAL_SHA256='20097fee8e81707c70b699992de09b0da8f100a86d58b0eecce2cb31e1ba5986'
ORIGINAL_PROBE_SHA256='6cfccbbc159a223a49e6892a96af4c83e0d7000660a8bb61009599c1dd409539'
CORRECTED_PROBE_SHA256='a7c79ac0eaf329855840fe7b65274f15a0a46bf32cd237a7d2a33129ee1a431d'
CORRECTED_PROBE=''
import base64
import hashlib
import importlib.util
from pathlib import Path

ORIGINAL=Path('/root/wakhan-update-0211.py')


def load_installer(file=ORIGINAL):
    if not file.is_file() or file.is_symlink() or hashlib.sha256(file.read_bytes()).hexdigest()!=ORIGINAL_SHA256:
        raise RuntimeError('EXPECTED_ORIGINAL_0211_INSTALLER_REQUIRED')
    spec=importlib.util.spec_from_file_location('wakhan_verified_0211',file)
    module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
    unpack=module.unpack
    def repaired_unpack(work):
        unpack(work)
        probe=work/'release_probe.py'
        if hashlib.sha256(probe.read_bytes()).hexdigest()!=ORIGINAL_PROBE_SHA256:
            raise RuntimeError('EXPECTED_ORIGINAL_0211_PROBE_REQUIRED')
        code=base64.b64decode(CORRECTED_PROBE)
        if hashlib.sha256(code).hexdigest()!=CORRECTED_PROBE_SHA256:
            raise RuntimeError('CORRECTED_PROBE_CHECKSUM_FAILED')
        compile(code,'release_probe.py','exec');probe.write_bytes(code)
    module.unpack=repaired_unpack
    return module


def main():
    print('RESUMING_0211_WITH_VERIFIED_VERSION_CHECK',flush=True)
    load_installer().main()


if __name__=='__main__':main()
